#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
: "${DATABASE_URL:?Supply a PostgreSQL administrator URL for isolated SQLx test databases}"
contract_output=$(mktemp -d)
trap 'rm -rf "$contract_output"' EXIT
export EXPOSED_CONTRACT_OUTPUT_DIR="$contract_output"
# Test queries compile online against the supplied schema. SQLx owns isolated test databases.
SQLX_OFFLINE=false cargo test --locked -p exposed --lib outbound::entity_details::tests
npm --prefix frontend run check
npm --prefix frontend run build
(cd frontend && PLAYWRIGHT_BROWSERS_PATH=0 npx playwright test tests/member-summary.spec.ts tests/entity-details.spec.ts)
(cd frontend && PLAYWRIGHT_BROWSERS_PATH=0 npx playwright test --config playwright.contract.config.ts)
# Declared GBP totals contract v1

The backend owns both headlines. All categories participate; dates are registration
timestamps. The current term starts inclusively at 2024-07-09 00:00:00 UTC.
Undated declarations belong only to historical totals. Known GBP amounts add
exactly, including duplicates, negatives and zero. Missing GBP amounts and unknown
currencies mark coverage incomplete. Foreign currency amounts do not convert into
GBP or make GBP coverage incomplete. A missing sum remains null, not zero.

`fixture.sql` and `expected.json` are a small frozen baseline. The first member's
historical total is 100 + 200 + 30.25 - 5 + .1 + .1 + 7.55 = 333.
Excluding the pre-term 100 and undated 7.55 gives 225.45 for the current term.
Other members distinguish exact cancellation, empty history, foreign-only,
missing-only, and a declaration without entries.

With frontend dependencies and Playwright Chromium installed, run from the root:

```sh
DATABASE_URL=postgres://localhost/exposed_test scripts/check-declared-totals-contract.sh
```

The supplied database must already have the application schema for SQLx compile
checks, and its role must create databases. SQLx applies migrations and the fixture
in isolated test databases. The script does not import or update source records.
The Rust test asserts actual Axum responses against the baseline, then exports
those bytes into a temporary directory. Browser tests feed those responses through
the existing HTTP stub into the built Svelte application. Contract mode fails when
the fresh response files are absent. Ordinary browser tests do not select it.

CI runs on every PR and takes both baseline files from the PR target commit before
compilation. The first PR bootstraps only when that target has neither baseline
nor guard workflow/script; it logs that exception. Partial or subsequently missing
baselines fail. Requested semantic migrations need an explicit new version and
reviewed retirement of the previous contract. Editing expectations to match a
regression is not a fix. The repository check cannot stop coordinated edits to the
check itself; required checks and review rules must be configured on GitHub.
import { defineConfig } from "@playwright/test";
import config from "./playwright.config";

if (!process.env.EXPOSED_CONTRACT_OUTPUT_DIR)
  throw new Error(
    "EXPOSED_CONTRACT_OUTPUT_DIR must contain fresh Rust HTTP responses",
  );

export default defineConfig({
  ...config,
  testMatch: "declared-totals.contract.ts",
});
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { expect, test } from "./backend";

const output = process.env.EXPOSED_CONTRACT_OUTPUT_DIR;
if (!output) throw new Error("Missing fresh Rust HTTP response directory");
const expected: Record<
  string,
  {
    display: string[];
    declared_totals: {
      current_term: {
        amount: string | null;
        declaration_count: number;
        incomplete: boolean;
      };
      historical: {
        amount: string | null;
        declaration_count: number;
        incomplete: boolean;
      };
    };
  }
> = JSON.parse(
  readFileSync(
    new URL(
      "../../contracts/declared-totals-v1/expected.json",
      import.meta.url,
    ),
    "utf8",
  ),
);
// These are actual Axum response bodies, written only after Rust's baseline assertions pass.
const responses: Record<string, string> = Object.fromEntries(
  Object.keys(expected).map((id) => [
    id,
    readFileSync(join(output, `${id}.json`), "utf8"),
  ]),
);

for (const [id, contract] of Object.entries(expected)) {
  test(`real backend declared GBP contract renders member ${id}`, async ({
    backend,
    page,
  }) => {
    await backend.route(`**/api/members/${id}`, (route) =>
      route.fulfill({
        body: responses[id],
        contentType: "application/json",
      }),
    );
    await page.goto(`/members/${id}`);
    await expect(page.locator(".member-total")).toHaveText(contract.display);
    await expect(page.locator(".member-earnings-totals h2").first()).toHaveText(
      "Declared amounts this parliamentary term",
    );
    await expect(
      page.locator(".member-earnings-totals h2").last(),
    ).toContainText("Historical declared amounts");
    for (const [index, period] of [
      contract.declared_totals.current_term,
      contract.declared_totals.historical,
    ].entries()) {
      if (period.amount !== null && period.declaration_count > 0) {
        const figure = page.locator(".member-total").nth(index);
        await expect(figure).toHaveAttribute(
          "aria-label",
          index === 0
            ? "Declared amounts this parliamentary term in GBP"
            : "Historical declared amounts in GBP",
        );
        if (period.incomplete)
          await expect(figure).toHaveAttribute(
            "title",
            "Known GBP amounts only. Some amounts unavailable.",
          );
        else await expect(figure).not.toHaveAttribute("title");
      }
    }
  });
}

test("authoritative headlines survive contradictory declarations", async ({
  backend,
  page,
}) => {
  const body = record(JSON.parse(responses["7001"]));
  body.declarations = [];
  await backend.route("**/api/members/7001", (route) =>
    route.fulfill({ json: body }),
  );
  await page.goto("/members/7001");
  await expect(page.locator(".member-total")).toHaveText(
    expected["7001"].display,
  );
});

const corruptions: { name: string; path: string[]; value?: unknown }[] = [
  { name: "missing declared totals", path: [] },
  { name: "missing amount", path: ["current_term", "amount"] },
  { name: "missing period", path: ["historical"] },
  { name: "invalid amount", path: ["historical", "amount"], value: 333 },
  {
    name: "invalid count",
    path: ["historical", "declaration_count"],
    value: -1,
  },
  { name: "missing count", path: ["current_term", "declaration_count"] },
  {
    name: "invalid boolean",
    path: ["current_term", "incomplete"],
    value: "false",
  },
  { name: "missing boolean", path: ["historical", "incomplete"] },
  { name: "null start", path: ["current_term_start"], value: null },
  { name: "invalid start", path: ["current_term_start"], value: "not a date" },
  { name: "missing start", path: ["current_term_start"] },
];
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  if (!isRecord(value)) throw new Error("Expected a contract response object");
  return value;
}
for (const { name, path, value } of corruptions) {
  test(`mandatory headline fields fail closed: ${name}`, async ({
    backend,
    page,
  }) => {
    const body: unknown = JSON.parse(responses["7001"]);
    let parent = record(record(body).summary);
    const keys = ["declared_totals", ...path];
    const key = keys.pop();
    if (key === undefined) throw new Error("Missing corruption field");
    for (const field of keys) parent = record(parent[field]);
    if (value === undefined) delete parent[key];
    else parent[key] = value;
    await backend.route("**/api/members/7001", (route) =>
      route.fulfill({ json: body }),
    );
    await page.goto("/members/7001");
    await expect(
      page.getByText("Details returned an unexpected response. Try again."),
    ).toBeVisible();
    await expect(page.locator(".member-total")).toHaveCount(0);
  });
}
